optimum:
petra 0

# A tee hanger: a WT9x25 bolted to the bottom flange of a W18x50 with two rows of two 3/4 in
# Group 120 bolts, carrying a tension in its stem. Prying is checked by the T-stub model.

design "steel-hanger" {
  owner "s.engineer@example.org"
}

hanger h1 {
  basis asd
  support W16x31 flange grade steel.A992
  tee WT8x15_5 grade steel.A992
  bolts bolt_group.120 diameter 0.75 inch threads included joint pretensioned
  rows 2
  pitch 3 inch
  tee_gauge 3.25 inch
  edge_vertical 1.5 inch
}

load task {
  on h1 tension in [0 kip, 34.745 kip]
  signed "task.owner@example.org" source "task 303-005"
}

petra 0

# An eccentrically loaded welded bracket: a 1/2 in A36 plate fillet-welded both sides to a
# column flange over 12 in, loaded 6 in from the weld line.

design "steel-weld-bracket" {
  owner "s.engineer@example.org"
}

weld_bracket wb1 {
  basis asd
  support W12x40 flange grade steel.A992
  eccentricity 5 inch
  plate steel.A36 thickness 0.5 inch
  weld electrode.E70 size 0.3125 inch sides 2
  weld_length 13.5625 inch
}

load task {
  on wb1 shear in [0 kip, 48.42 kip]
  signed "task.owner@example.org" source "task 303-022"
}
